#define rot(a) mat2(cos(a+vec4(0,11,33,0)))

//formula for creating colors;
#define H(h)  (  cos( h*2. + 7.*vec3(1,2,3) )*.4 + .3 )

//formula for mapping scale factor 
#define M(c)  log(1.+c)

#define R iResolution
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 uv = (fragCoord.xy / iResolution.xy) - .5;
	float t = iTime * .1 + ((.25 + .05 * sin(iTime * .1))/(length(uv.xy) + .07)) * 0.2;
	float si = sin(t);
	float co = cos(t);
	mat2 ma = mat2(co, si, -si, co);
    vec4 O =fragColor;
    vec2 U=fragCoord;
 float wfac = .6; //play with this
    O = vec4(0); 
    vec3 c=vec3(0); 
     vec3 r = normalize(vec3(uv, 1.0 - dot(uv, uv) *3.3));
    vec4 rd = normalize( vec4(U-.5*R.xy, .8*R.y, wfac*R.y))*12.; 

r.xy*=rot(iTime);
    float sc,dotp,totdist=0., t3=iTime/2.;

    float fac=.54, zoom=0.;

float t2 = mod(iTime,10.);

        zoom = (t2/R.y-.5)*4.;


        fac -= min(.065,max( .5*sin(t3*2.),0.));

  // pixel position normalised to [-1, 1]
	vec2 cPos = -1.0 + 2.0 * fragCoord.xy / iResolution.xy;

    // distance of current pixel from center
	float cLength = length(cPos);




    for (float i=0.; i<100.; i++) {

        vec4 p = vec4( rd*totdist );
           r.xy*=ma;
     p.xyz*=r;
        p.z -= 1.2 + zoom;

   p.xy*=ma;

        sc = .9;  

        for (float j=0.; j<7.; j++) {

            p = abs(p)*.67;

            dotp = max(1./dot(p,p),fac);
            sc *= dotp;

            p=p.x<p.y?p.wzxy:p.wzyx;
            p=p.z<p.w?p.xywz:p.xyzw;
            p=p.y<p.z?p.xwyz:p.xwzy;

            p *= dotp - .18*p;

        }


        float dist = clamp(abs( length(p-p.w) -.4)/(1.+sc),1e-4,1.) ; 
        float stepsize = dist + 1e-4  ;
        totdist += stepsize;    

        c += .2 *H(M(sc))*  exp(-i*i*stepsize*stepsize*2e3)
        ;


    }

    c = clamp(c,-100.,100.);
vec4 o=fragColor;
vec2 u=fragCoord;
vec2 v = iResolution.xy;
         u = .2*(u+u-v)/v.y;    

    vec4 z = o = vec4(1,2,3,0);

    for (float a = .5, t = iTime*0.1, i; 
         ++i < 19.; 
         o += (1. + cos(z+t)) 
            / length((1.+i*dot(v,v)) 
                   * sin(1.5*u/(.5-dot(u,u)) - 9.*u.yx + t))
         )  
        v = cos(++t - 7.*u*pow(a += .03, i)) - 5.*u,                 
        u += tanh(40. * dot(u *= mat2(cos(i + .02*t - vec4(0,11,33,0)))
                           ,u)
                      * cos(1e2*u.yx + t)) / 2e2
           + .2 * a * u
           + cos(4./exp(dot(o,o)/1e2) + t) / 3e2;

     o = 25.6 / (min(o, 13.) + 164. / o) 
       - dot(u, u) / 250.;

    c = 1. - exp(-c*c);

    c *= exp(-totdist*totdist/2.);

    c.b *= 1.5;

	float v1, v2, v3;
	v1 = v2 = v3 = 0.0;

	float s = 0.0;
	for (int i = 0; i < 90; i++)
	{
		vec3 p = s * vec3(uv, 0.0)*c.xyz*o.xyz;
	 p.xy+= (cPos/cLength)*cos(cLength*12.0-iTime*4.0) * 0.03;
     p.xy*=ma;
		p += vec3(.22, .3, s - 1.5 - sin(iTime * .13) * .1);
		for (int i = 0; i < 8; i++)	p = abs(p) / dot(p,p) - 0.659;
		v1 += dot(p,p) * .0015 * (1.8 + sin(length(uv.xy * 13.0) + .5  - iTime * .2));
		v2 += dot(p,p) * .0013 * (1.5 + sin(length(uv.xy * 14.5) + 1.2 - iTime * .3));
		v3 += length(p.xy*10.) * .0003;
		s  += .035;
	}

	float len = length(uv);
	v1 *= smoothstep(.7, .0, len);
	v2 *= smoothstep(.5, .0, len);
	v3 *= smoothstep(.9, .0, len);

	vec3 col = vec3( v3 * (1.5 + sin(iTime * .2) * .4),
					(v1 + v3) * .3,
					 v2) + smoothstep(0.2, .0, len) * .85 + smoothstep(.0, .6, v3) * .3;

	fragColor=vec4(min(pow(abs(col+(c.xyz+o.xyz)*0.5), vec3(1.2)), 1.0), 1.0);
}
